  function lookup(s){
    if(Object.prototype.hasOwnProperty.call(EXACT,s)) return EXACT[s];
    for(const [re,to] of PATTERNS) if(re.test(s)) return s.replace(re,to);
    return null;
  }
  // Czas podróży zostaje po polsku w środku przetłumaczonych zdań.
  const hours=s=>s.replace(/(\d+) godz\.(?= |$)/g,'$1 h');
  function translate(s){
    const direct=lookup(s); if(direct!=null) return hours(direct);
    const wrapped=s.match(/^((?:· )?[(„]*)(.*?)([)”.,:]*)$/s);
    if(wrapped && (wrapped[1]||wrapped[3])){ const inner=lookup(wrapped[2]); if(inner!=null) return wrapped[1]+hours(inner)+wrapped[3]; }
    if(s.includes(' · ')){ const parts=s.split(' · '), done=parts.map(p=>p.trim()?translate(p.trim()):p); if(done.some((p,i)=>p!==parts[i])) return done.join(' · '); }
    return s;
  }
  function translateText(text){
    const core=text.trim(); if(!core || !/\p{L}/u.test(core)) return text;
    const flat=core.replace(/\s+/g,' '), out=translate(flat); if(out===flat) return text;
    return text.slice(0,text.indexOf(core))+out+text.slice(text.indexOf(core)+core.length);
  }
  const SKIP=new Set(['SCRIPT','STYLE','TEXTAREA','CODE']);
  function textNode(n){ const p=n.parentNode; if(!p||SKIP.has(p.nodeName)) return; const t=translateText(n.nodeValue); if(t!==n.nodeValue) n.nodeValue=t; }
  function attrs(el){ for(const a of ['placeholder','title','aria-label']){ const v=el.getAttribute(a); if(v){ const t=translateText(v); if(t!==v) el.setAttribute(a,t); } } }
  function walk(root){
    if(root.nodeType===3){ textNode(root); return; }
    if(root.nodeType!==1 || SKIP.has(root.nodeName)) return;
    attrs(root);
    const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT); let n;
    while((n=w.nextNode())){ if(n.nodeType===3) textNode(n); else attrs(n); }
  }
  new MutationObserver(list=>{
    for(const m of list){
      if(m.type==='characterData') textNode(m.target);
      else if(m.type==='attributes') attrs(m.target);
      else m.addedNodes.forEach(walk);
    }
  }).observe(document,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','aria-label']});
  walk(document.documentElement);
  const brand=()=>document.querySelectorAll('[data-brand]').forEach(el=>{ const tag=el.querySelector('b,span')?.tagName.toLowerCase()||'b'; el.innerHTML='ON<'+tag+'>/</'+tag+'>WARD'; });
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', brand); else brand();
  window.rzTranslate=translateText;
